import { z } from 'zod';

/** UUIDv7 identifier generated by the application (data model §1). */
export const idSchema = z
  .uuidv7()
  .meta({ id: 'Id', example: '0192f6c4-7b1e-7c3a-9d2e-5f8a1b2c3d4e' });

/** ISO 8601 UTC timestamp with `Z` (BACKEND.md §5.4). */
export const timestampSchema = z.iso
  .datetime()
  .meta({ id: 'Timestamp', example: '2026-10-11T14:30:00Z' });

/** Calendar date `YYYY-MM-DD`. */
export const dateSchema = z.iso.date().meta({ id: 'Date', example: '2026-10-11' });

/** Local wall time `HH:mm`, interpreted in the owning location's timezone. */
export const localTimeSchema = z
  .string()
  .regex(/^([01]\d|2[0-3]):[0-5]\d$/, 'Expected HH:mm')
  .meta({ id: 'LocalTime', example: '09:30' });

/** Money in integer minor units plus ISO 4217 currency — never floats. */
export const moneySchema = z
  .object({
    amountMinor: z.int(),
    currency: z
      .string()
      .length(3)
      .regex(/^[A-Z]{3}$/),
  })
  .meta({ id: 'Money' });

/** Email address, trimmed and lower-cased (unique per realm, case-insensitive). */
export const emailSchema = z
  .string()
  .trim()
  .max(254)
  .pipe(z.email())
  .transform((v) => v.toLowerCase())
  .meta({ id: 'Email', example: 'owner@example.com' });

/** IANA time zone name, e.g. `Europe/Berlin` (never an offset). */
export const timezoneSchema = z
  .string()
  .max(64)
  .refine((tz) => {
    if (!/^[A-Za-z_]+(\/[A-Za-z0-9_+-]+)*$/.test(tz)) return false;
    try {
      new Intl.DateTimeFormat('en-US', { timeZone: tz });
      return true;
    } catch {
      return false;
    }
  }, 'Expected an IANA time zone such as Europe/Berlin')
  .meta({ id: 'TimeZone', example: 'Europe/Berlin' });

/** BCP 47 language tag, canonicalized (`en`, `en-GB`, `ur-PK`). */
export const localeSchema = z
  .string()
  .max(35)
  .transform((tag, ctx) => {
    try {
      const [canonical] = Intl.getCanonicalLocales(tag);
      if (canonical) return canonical;
    } catch {
      // fall through
    }
    ctx.addIssue({ code: 'custom', message: 'Expected a BCP 47 language tag such as en-GB' });
    return z.NEVER;
  })
  .meta({ id: 'Locale', example: 'en-GB' });

/** Phone number in E.164 (`+923001234567`). */
export const phoneE164Schema = z
  .string()
  .regex(/^\+[1-9]\d{6,14}$/, 'Expected an E.164 phone number such as +923001234567')
  .meta({ id: 'PhoneE164', example: '+923001234567' });
